// 🔐 Security headers (SSL/HSTS + anti-clickjacking + MIME sniffing protection)
app.use((_req, res, next) => {
  res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "SAMEORIGIN");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader("Permissions-Policy", "camera=(self), microphone=(self), geolocation=(self)");
  next();
});

app.use(express.json({ limit: "8mb" })); // ⬇️ 512MB RAM पर OOM से बचाव

// The bundled Android WebView uses this exact HTTPS virtual origin. Keep it allowed
// even when APP_ORIGINS is explicitly set in the host environment, so OTP preflight
// requests work in the APK without opening CORS broadly.
const APP_ORIGINS = Array.from(new Set([
  ...String(
    process.env.APP_ORIGINS ||
    "https://wrong-chat-skl8.onrender.com,http://localhost:3000,http://127.0.0.1:3000"
  )
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean),
  "https://app.wrongchat.local",
]));

app.disable("x-powered-by");

// ---------- 1) रेट-लिमिट (in-memory, कोई पैकेज नहीं) ----------
const RL_BUCKETS = new Map();
function rateLimit({ windowMs = 60000, max = 300, key = "general" } = {}) {
  return (req, res, next) => {
    const ip =
      String(req.headers["cf-connecting-ip"] || req.headers["x-forwarded-for"] || req.socket.remoteAddress || "")
        .split(",")[0]
        .trim() || "unknown";
    const bucketKey = `${key}:${ip}`;
    const now = Date.now();
    let rec = RL_BUCKETS.get(bucketKey);
    if (!rec || now > rec.resetAt) {
      rec = { count: 0, resetAt: now + windowMs };
      RL_BUCKETS.set(bucketKey, rec);
    }
    rec.count += 1;
    const remaining = Math.max(0, max - rec.count);
    res.setHeader("X-RateLimit-Limit", String(max));
    res.setHeader("X-RateLimit-Remaining", String(remaining));
    res.setHeader("X-RateLimit-Reset", String(Math.ceil(rec.resetAt / 1000)));
    if (rec.count > max) {
      res.setHeader("Retry-After", String(Math.ceil((rec.resetAt - now) / 1000)));
      return res.status(429).json({
        ok: false,
        error: "Too many attempts — please try again after 1 minute.",
      });
    }
    next();
  };
}
// हर 5 मिनट में पुराने bucket साफ़ करें
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of RL_BUCKETS) if (now > v.resetAt + 60000) RL_BUCKETS.delete(k);
}, 5 * 60 * 1000);

// ---------- 2) सख़्त CORS ----------
app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowed = !origin || origin === "null" || APP_ORIGINS.includes(origin);
  if (allowed && origin) {
    res.setHeader("Access-Control-Allow-Origin", origin === "null" ? "null" : origin);
    res.setHeader("Vary", "Origin");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization, apikey");
    res.setHeader("Access-Control-Max-Age", "86400");
  }
  if (req.method === "OPTIONS") {
    return allowed ? res.status(204).end() : res.status(403).json({ ok: false, error: "Origin not allowed" });
  }
  next();
});

// ---------- 3) CSP + अतिरिक्त सुरक्षा हेडर ----------
app.use((_req, res, next) => {
  res.setHeader(
    "Content-Security-Policy",
    [
      "default-src 'self'",
      // 🔐 'unsafe-inline' हटाया — इसी से securityheaders.com A → A+ और Mozilla Observatory B+ → A
      "script-src 'self'",
      "script-src-attr 'none'",
      "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
      "font-src 'self' data: https://fonts.gstatic.com",
      "img-src 'self' data: blob: https:",
      "media-src 'self' data: blob: https:",
      "connect-src 'self' https: wss:",
      "frame-src 'self' https:",
      "object-src 'none'",
      "base-uri 'self'",
      "form-action 'self'",
      "frame-ancestors 'self'",
      "upgrade-insecure-requests",
    ].join("; ")
  );
  res.setHeader("Cross-Origin-Opener-Policy", "same-origin-allow-popups");
  res.setHeader("Cross-Origin-Resource-Policy", "same-origin");
  res.setHeader("X-Permitted-Cross-Domain-Policies", "none");
  next();
});

